items.body:
Query:

```
{
  curatedList {
     ...on Program {
        title(lang: "fi")
     }

     ...on Article {
        title
     }
  }
}
```

Error:

```
Fields title conflict because they have differing arguments.
```

Should it really work like that, or is this a bug?

Article and Program are both members of union type Content

Types on the same union are expected to have matching nullability constraints even when the fragments can never converge.

Given this schema:

```graphql

type Cat {
  name: String!
}

type Dog  {
  name: String
}

union Pet = Cat | Dog

type Query {
  pet: Pet
}
```

and this operation:

```graphql
{
  pet {
    ... on Cat {
      name
    }
    ... on Dog {
      name
    }
  }
}

```


The execution results in a validation error:

> GraphQLError: Fields "name" conflict because they return conflicting types String! and String. Use different aliases on the fields to fetch both if this was intentional.

Related issue: #53 

Repro script:

`node test.js`

`test.js`
```js

var {
  graphql,
  GraphQLSchema,
  GraphQLNonNull,
  GraphQLObjectType,
  GraphQLUnionType,
  GraphQLString
} = require("graphql");

var CatType = new GraphQLObjectType({
  name: 'Cat',
  fields: () => ({
    name: { type: new GraphQLNonNull(GraphQLString) },
  })
});

var DogType = new GraphQLObjectType({
  name: 'Dog',
  fields: () => ({
    name: { type: GraphQLString },
  })
});

var PetType = new GraphQLUnionType({
  name: 'Pet',
  types: [ DogType, CatType ],
  resolveType(value) {
    return DogType;
  }
});

var schema = new GraphQLSchema({
  query: new GraphQLObjectType({
    name: 'RootQueryType',
    fields: {
      pet: {
        type: PetType,
        resolve() {
          return 'pet';
        }
      }
    }
  })
});

var query = `{
  pet {
    ... on Cat {
      name
    }
    ... on Dog {
      name
    }
  }
}`;

graphql(schema, query).then(result => {
  // Prints error
  // GraphQLError: Fields "name" conflict because they return conflicting types String! and String. Use different aliases on the fields to fetch both if this was intentional.
  console.log(result);
});
```


